#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/aff3ct/turbo_decoder.h>

void bind_turbo_decoder(py::module& m)
{
    using turbo_decoder = ::gr::aff3ct::turbo_decoder;

    py::class_<turbo_decoder, gr::fec::generic_decoder, std::shared_ptr<turbo_decoder>>(
        m,
        "turbo_decoder",
        py::multiple_inheritance(), // generic_decoder is a virtual base: pointers must be adjusted
        "AFF3CT turbo decoder (LTE constituent codes, any K and N).")
        .def_static("make",
                    &turbo_decoder::make,
                    py::arg("K"),
                    py::arg("N"),
                    py::arg("n_ite") = 6,
                    py::arg("interleaver") = "AUTO",
                    py::arg("seed") = 0,
                    py::arg("precision") = "int16",
                    py::arg("simd") = "INTER",
                    py::arg("frames") = 0,
                    py::arg("llr_scale") = 1.0f,
                    py::arg("aff3ct_args") = "")
        .def("frames", &turbo_decoder::frames)
        .def("interleaver", &turbo_decoder::interleaver);
}
